import json
from typing import Any, Dict

def _offers_of(obj):
    # V3.12 多商品：优先取 offers[] 数组；旧单品平面对象包装为 1 品（offer_seq=1）
    if not isinstance(obj, dict):
        return []
    offers = obj.get('offers')
    if isinstance(offers, list):
        out = []
        for i, o in enumerate(offers, start=1):
            if not isinstance(o, dict):
                continue
            e = dict(o)
            e.setdefault('offer_seq', i)
            out.append(e)
        return out
    return [obj]

async def main(args):
    raw = args.params['query_list']
    if not isinstance(raw, str):
        raw = json.dumps(raw, ensure_ascii=False)
    record_json = ''
    offer_id = ''
    req_id = ''
    try:
        arr = json.loads(raw)
        if isinstance(arr, list) and arr:
            first = arr[0]
            if isinstance(first, dict):
                record_json = str(first.get('result_json') or '')
                req_id = str(first.get('req_id') or '')
        elif isinstance(arr, dict):
            record_json = str(arr.get('result_json') or '')
            req_id = str(arr.get('req_id') or '')
    except Exception:
        record_json = ''
    if not record_json:
        record_json = raw
    offers = []
    try:
        inner = json.loads(record_json)
        if isinstance(inner, dict):
            if not req_id:
                req_id = str(inner.get('req_id') or '')
            offers = _offers_of(inner)
            if offers:
                offer_id = str(offers[0].get('offer_id') or offers[0].get('offerId') or '')
    except Exception:
        offers = []
    ret: Output = {
        "record_json": record_json,
        "req_id": req_id,
        "offer_id": offer_id,
        "offers": json.dumps(offers, ensure_ascii=False)
    }
    return ret

import json
from typing import Any, Dict

def _load(v):
    if isinstance(v, list):
        return v
    if isinstance(v, dict):
        return v.get('offers') if isinstance(v.get('offers'), list) else [v]
    if not isinstance(v, str) or not v.strip():
        return []
    try:
        obj = json.loads(v)
        if isinstance(obj, dict) and isinstance(obj.get('offers'), list):
            return obj['offers']
        return obj if isinstance(obj, list) else ([obj] if isinstance(obj, dict) else [])
    except Exception:
        return []

def _inner(o):
    # config 环节 offer 的真实名称在 product_config（JSON字符串）内，需下钻一层
    pc = o.get('product_config')
    if isinstance(pc, str):
        try:
            pc = json.loads(pc)
        except Exception:
            pc = None
    return pc if isinstance(pc, dict) else o

def _name(o, seq):
    src = _inner(o)
    plan = src.get('plan_json')
    if isinstance(plan, str):
        try:
            plan = json.loads(plan)
        except Exception:
            plan = None
    base = plan.get('baseInfo') if isinstance(plan, dict) and isinstance(plan.get('baseInfo'), dict) else {}
    nm = str(base.get('prodPrcName') or src.get('offer_name') or o.get('offer_name') or o.get('name') or '').strip()
    if not nm:
        oid = str(o.get('offer_id') or o.get('offerId') or '').strip()
        nm = ('新增销售品%s' % oid) if oid else ('商品%s' % seq)
    return nm

async def main(args):
    p = args.params
    cfg_offers = [o for o in _load(p.get('config_offers')) if isinstance(o, dict)]
    res_offers = [o for o in _load(p.get('result_offers')) if isinstance(o, dict)]
    pass_by_seq: Dict[Any, str] = {}
    for o in res_offers:
        pass_by_seq[str(o.get('offer_seq'))] = str(o.get('pass') or '')
    lines = []
    for i, o in enumerate(cfg_offers, start=1):
        seq = o.get('offer_seq')
        seq = seq if seq not in (None, '') else i
        oid = str(o.get('offer_id') or o.get('offerId') or '').strip()
        verdict = pass_by_seq.get(str(seq), '')
        mark = '通过' if verdict == '1' else ('未通过' if verdict == '0' else '—')
        lines.append('%d. %s（销售品ID=%s）：%s' % (i, _name(o, seq), oid or '—', mark))
    if not lines and res_offers:
        for i, o in enumerate(res_offers, start=1):
            seq = o.get('offer_seq') or i
            verdict = str(o.get('pass') or '')
            mark = '通过' if verdict == '1' else ('未通过' if verdict == '0' else '—')
            lines.append('%d. 商品%s：%s' % (i, seq, mark))
    ret: Output = {'offer_list_text': '\n'.join(lines)}
    return ret

