async def main(args):
    offers = [o for o in _load(args.params.get('offers')) if isinstance(o, dict)]
    pass_top = args.params.get('pass')
    if pass_top is None or str(pass_top) == '':
        vals = [str(o.get('pass') or '') for o in offers]
        pass_top = '1' if vals and all(v == '1' for v in vals) else ('0' if vals else '')
    risks = []
    for o in offers:
        rl = o.get('risk_list')
        if isinstance(rl, list):
            for r in rl:
                if isinstance(r, dict):
                    r.setdefault('offer_seq', o.get('offer_seq'))
                    risks.append(r)
    ret: Output = {
        'pass': str(pass_top),
        'offers': json.dumps(offers, ensure_ascii=False),
        'risk_list': json.dumps(risks, ensure_ascii=False) if risks else '',
    }
    return ret

import json
from typing import Any, Dict

def _roster_map(raw):
    # 权威名册归一：入参可为 [{offer_seq,name,quantity}] / {offers:[...]} / JSON 字符串
    obj = raw
    if isinstance(obj, str):
        try:
            obj = json.loads(obj)
        except Exception:
            obj = None
    if isinstance(obj, dict):
        obj = obj.get('offers')
    if not isinstance(obj, list):
        return {}
    out = {}
    for i, o in enumerate(obj, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        name = str(o.get('name') or '').strip()
        qty = o.get('quantity')
        if name or qty not in (None, ''):
            out[seq] = {'name': name, 'quantity': qty}
    return out

def _merge_roster(offers, raw):
    # 按 offer_seq 把权威名册的 name/quantity 合并进逐品元素（已有非空 name 不覆盖）
    roster = _roster_map(raw)
    if not roster or not isinstance(offers, list):
        return offers
    for i, o in enumerate(offers, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        r = roster.get(seq)
        if not r:
            continue
        if r.get('name') and not str(o.get('name') or '').strip():
            o['name'] = r['name']
        if r.get('quantity') not in (None, '') and o.get('quantity') in (None, ''):
            o['quantity'] = r['quantity']
    return offers

_PASSTHROUGH = ('pass', 'error_list', 'audit_summary', 'risk_list', 'compare_list',
                'requestIds', 'sales_id', 'file_id', 'globalId', 'testScenes', 'offer_id',
                'offers', 'req_id', 'plan_json')

def _any(v):
    # 平台出参可能是已序列化 JSON 字符串，也可能是原始 list/str；统一尝试解析
    if isinstance(v, (list, dict)):
        return v
    if v is None:
        return None
    s = str(v)
    if not s.strip():
        return None
    t = s.strip()
    if t[0] in '[{' and t[-1] in ']}':
        try:
            return json.loads(t)
        except Exception:
            return s
    return s

async def main(args):
    p = args.params
    env: Dict[str, Any] = {}
    for key in _PASSTHROUGH:
        if key in p and p.get(key) is not None and str(p.get(key)) != '':
            env[key] = _any(p.get(key))
    # V3.14：若提供权威名册（roster_name/roster 入参），按 offer_seq 把 name/quantity
    # 合并进落库 offers[]，保证下游销售品文案前后一致（名册缺失时零变化）。
    roster = p.get('roster') or p.get('roster_name') or ''
    if roster and isinstance(env.get('offers'), list):
        env['offers'] = _merge_roster(env['offers'], roster)
    md = str(p.get('md') or p.get('markdown') or '')
    md_key = str(p.get('md_key') or 'report_md')
    if md:
        env[md_key] = md
        # 兼容占位：老消费方仅认 raw 时可回退取值
        env.setdefault('raw', md)
    ret: Output = {
        'record_json': json.dumps(env, ensure_ascii=False)
    }
    return ret

